Here's a modern MSTest approach using `MockHttpMessageHandler`, async test methods, and proper cancellation/timeout patterns:

```csharp
[TestClass]
public class DataFetcherTests
{
    // Helper: creates an HttpClient backed by a custom handler
    private static HttpClient CreateMockClient(
        HttpStatusCode status, string content)
    {
        var handler = new MockHandler(status, content);
        return new HttpClient(handler);
    }

    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        using var client = CreateMockClient(HttpStatusCode.OK, "hello");
        var fetcher = new DataFetcher(client);

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    [TestMethod]
    public async Task FetchAsync_Throws_OnNonSuccessStatus()
    {
        using var client = CreateMockClient(HttpStatusCode.InternalServerError, "");
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    // MSTest [Timeout] is in milliseconds and works with async tests.
    // If FetchAsync hangs, the test fails after 1 second instead of blocking forever.
    [TestMethod]
    [Timeout(1000)]
    public async Task FetchAsync_CompletesWithinTimeout()
    {
        using var client = CreateMockClient(HttpStatusCode.OK, "fast");
        var fetcher = new DataFetcher(client);

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("fast", result);
    }

    [TestMethod]
    public async Task FetchAsync_ThrowsOnCancellation()
    {
        // Pre-cancelled token
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        using var client = CreateMockClient(HttpStatusCode.OK, "data");
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    public async Task FetchAsync_HonoursCancellationDuringRequest()
    {
        // Handler that delays, giving us time to cancel mid-flight
        var handler = new DelayedHandler(TimeSpan.FromSeconds(5));
        using var client = new HttpClient(handler);
        using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(50));

        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // ── Minimal test doubles ──────────────────────────────────

    private sealed class MockHandler : HttpMessageHandler
    {
        private readonly HttpStatusCode _status;
        private readonly string _content;

        public MockHandler(HttpStatusCode status, string content)
        {
            _status = status;
            _content = content;
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var response = new HttpResponseMessage(_status)
            {
                Content = new StringContent(_content)
            };
            return Task.FromResult(response);
        }
    }

    private sealed class DelayedHandler : HttpMessageHandler
    {
        private readonly TimeSpan _delay;
        public DelayedHandler(TimeSpan delay) => _delay = delay;

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            await Task.Delay(_delay, cancellationToken);
            return new HttpResponseMessage(HttpStatusCode.OK);
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---|---|
| **Async tests** | `async Task` return type — MSTest awaits them natively |
| **Timeout** | `[Timeout(ms)]` attribute — fails the test if it hangs |
| **Cancellation** | Pre-cancelled token *and* mid-flight cancellation via `CancellationTokenSource(delay)` |
| **No external mocks** | Custom `HttpMessageHandler` subclasses — no Moq/NSubstitute needed |

The `[Timeout]` attribute is the MSTest-idiomatic way to guard against hangs; avoid manually wrapping with `Task.WhenAny` or `Task.Delay` unless you need custom timeout logic inside the test body.
